void Solver::bump_var(int var, double coeff) {
    const double THRESH = 1e100;
    const double RESCALE = 1e-100;
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;
    if (newAct > THRESH) {
        // Rescale all activities with loop unrolling for speed
        double *act = activity + 1;               // activity[1] ... activity[vars]
        int n = vars;
        int i = 0;
        for (; i + 3 < n; i += 4) {
            act[i]     *= RESCALE;
            act[i + 1] *= RESCALE;
            act[i + 2] *= RESCALE;
            act[i + 3] *= RESCALE;
        }
        for (; i < n; ++i) act[i] *= RESCALE;
        var_inc *= RESCALE;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}

