void Solver::bump_var(int var, double coeff) {
    const double THRESH  = 1e200;   // raise threshold to reduce rescaling frequency
    const double RESCALE = 1e-200;  // reciprocal of THRESH
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;
    if (newAct > THRESH) {
        // Rescale all variable activities without loop unrolling – simple pointer walk
        double *act = activity + 1;          // activity[1] .. activity[vars]
        int n = vars;
        while (n--) {
            *act++ *= RESCALE;
        }
        var_inc *= RESCALE;
    }
    if (vsids.inHeap(var)) vsids.update(var);
}

