void Solver::bump_var(int var, double coeff) {
    const double THRESH  = 1e150;   // higher threshold to reduce rescaling frequency
    const double RESCALE = 1e-150;  // reciprocal of THRESH
    double inc = var_inc * coeff;
    double newAct = activity[var] + inc;
    activity[var] = newAct;

    if (newAct > THRESH) {
        // Rescale all activities with manual loop unrolling (4-way)
        double *p = activity + 1;          // activity[1] .. activity[vars]
        int n = vars;
        while (n >= 4) {
            *p++ *= RESCALE;
            *p++ *= RESCALE;
            *p++ *= RESCALE;
            *p++ *= RESCALE;
            n -= 4;
        }
        while (n--) {
            *p++ *= RESCALE;
        }
        var_inc *= RESCALE;
    }
    if (vsids.inHeap(var)) {
        vsids.update(var);
    }
}

